    seen = set()
    components = []
    comp_at = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            idx = len(components)
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                comp_at[(y, x)] = idx
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            components.append(component)

    # Pair markers on opposite borders, producing horizontal/vertical rays.
    edge_rows = {r for r, c in markers if c in (0, w-1)}
    edge_cols = {c for r, c in markers if r in (0, h-1)}
    active_rows = {r for r in edge_rows if (r, 0) in markers and (r, w-1) in markers}
    active_cols = {c for c in edge_cols if (0, c) in markers and (h-1, c) in markers}

