            for c in range(start, w if step > 0 else -1, step):
                if grid[r][c] == 2:
                    selected.add(comp_at[(r, c)])
                    break
                if grid[r][c] == 0:
                    out[r][c] = 1
    for c in active_cols:
        for start, step in ((0, 1), (h-1, -1)):
            for r in range(start, h if step > 0 else -1, step):
                if grid[r][c] == 2:
                    selected.add(comp_at[(r, c)])
                    break
                if grid[r][c] == 0:
                    out[r][c] = 1

